"""Lossless native transport from an independently evaluated aggregate provider.

Three geometry instances keep the surface, physical evidence and status apart.
No transport attribute is added to either qualified geometry. The only status
attributes live on their own one-point mesh. Source-dependent construction is
still native GN; Python neither caches evaluated geometry nor handles edits.
"""
from . import boundary_quad_bridge_nodes as bridge


def packet(g, geometry, evidence, valid, key):
    status = g.node('GeometryNodeMeshLine', 'One aggregate provider status record')
    status.inputs['Count'].default_value = 1
    record = g.store(status.outputs['Mesh'], '_ag_provider_valid', valid, 'BOOLEAN')
    record = g.store(record, '_ag_provider_key', key, 'INT')
    record = g.store(record, '_ag_provider_version', 1, 'INT')
    instances = []
    for name, value in (('Surface', geometry), ('Physical evidence', evidence), ('Status', record)):
        node = g.node('GeometryNodeGeometryToInstance', 'Aggregate packet / '+name)
        g.set(value, node.inputs['Geometry']); instances.append(node.outputs['Instances'])
    # GN's multi-input ordering prepends links; the decoder uses this order.
    return bridge._join(g, *reversed(instances))


def unpack(g, inp):
    info = g.node('GeometryNodeObjectInfo', 'Native aggregate provider result')
    info.transform_space = 'ORIGINAL'
    g.set(inp.outputs['Aggregate Result'], info.inputs['Object'])
    geometry = info.outputs['Geometry']
    size = g.node('GeometryNodeAttributeDomainSize', 'Three aggregate packet components')
    size.component = 'INSTANCES'; g.set(geometry, size.inputs['Geometry'])
    parts = []
    index = g.node('GeometryNodeInputIndex', 'Aggregate packet part').outputs[0]
    for ordinal, name in enumerate(('Surface', 'Physical evidence', 'Status')):
        select = g.node('GeometryNodeSeparateGeometry', 'Read aggregate '+name)
        select.domain = 'INSTANCE'; g.set(geometry, select.inputs['Geometry'])
        g.set(g.compare(index, ordinal, kind='INT'), select.inputs['Selection'])
        realize = g.node('GeometryNodeRealizeInstances', 'Unpack aggregate '+name)
        g.set(select.outputs['Selection'], realize.inputs['Geometry']); parts.append(realize.outputs['Geometry'])
    status = parts[2]
    read = lambda name, kind: g.sample(status, g.named(name, kind), 0, kind)
    count = g.node('GeometryNodeAttributeDomainSize', 'One aggregate status record')
    count.component = 'MESH'; g.set(status, count.inputs['Geometry'])
    transport = g.all(g.compare(size.outputs['Instance Count'], 3, kind='INT'),
        g.compare(count.outputs['Point Count'], 1, kind='INT'),
        g.compare(inp.outputs['Aggregate Provider Key'], 0, 'GREATER_THAN', 'INT'),
        g.compare(read('_ag_provider_key', 'INT'), inp.outputs['Aggregate Provider Key'], kind='INT'),
        g.compare(read('_ag_provider_version', 'INT'), 1, kind='INT'))
    return (g.switch(transport, None, parts[0], 'GEOMETRY'),
            g.switch(transport, None, parts[1], 'GEOMETRY'),
            g.all(transport, read('_ag_provider_valid', 'BOOLEAN')))
